const updatePlacement = `-- name: UpdatePlacement :execrows
UPDATE placement SET
    post_version_id = $1, status = $2, status_changed_at = $3,
    status_reason = $4, sent_to_blogger_at = $5,
    accept_deadline_at = $6, schedule_deadline_at = $7,
    publish_at = $8, remove_at = $9, published_at = $10, removed_at = $11,
    claim_deadline_at = $12, final_views = $13, lock_version = $14,
    updated_at = $15
WHERE id = $16 AND status = $17 AND lock_version = $18
`

type UpdatePlacementParams struct {
	PostVersionID      uuid.UUID
	Status             string
	StatusChangedAt    time.Time
	StatusReason       *string
	SentToBloggerAt    *time.Time
	AcceptDeadlineAt   *time.Time
	ScheduleDeadlineAt *time.Time
	PublishAt          *time.Time
	RemoveAt           *time.Time
	PublishedAt        *time.Time
	RemovedAt          *time.Time
	ClaimDeadlineAt    *time.Time
	FinalViews         *int32
	LockVersion        int32
	UpdatedAt          time.Time
	ID                 uuid.UUID
	PrevStatus         string
	PrevLockVersion    int32
}

// Суммы и снимки не обновляются (I-05); условие — ожидаемые состояние и lock_version (03 §11).
func (q *Queries) UpdatePlacement(ctx context.Context, arg UpdatePlacementParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePlacement,
		arg.PostVersionID,
		arg.Status,
		arg.StatusChangedAt,
		arg.StatusReason,
		arg.SentToBloggerAt,
		arg.AcceptDeadlineAt,
		arg.ScheduleDeadlineAt,
		arg.PublishAt,
		arg.RemoveAt,
		arg.PublishedAt,
		arg.RemovedAt,
		arg.ClaimDeadlineAt,
		arg.FinalViews,
		arg.LockVersion,
		arg.UpdatedAt,
		arg.ID,
		arg.PrevStatus,
		arg.PrevLockVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
